<?= $this->extend('layouts/main') ?><?= $this->section('content') ?><div class="form-wrap"><h1><?= $producto ? 'Editar producto' : 'Nuevo producto' ?></h1><?php if ($errors = session()->getFlashdata('errors')): ?><div class="alert error"><?php foreach ($errors as $error): ?><div><?= esc($error) ?></div><?php endforeach; ?></div><?php endif; ?><form method="post" action="<?= site_url($producto ? 'admin/productos/actualizar/' . $producto['idProducto'] : 'admin/productos/guardar') ?>"><?= csrf_field() ?><label>Nombre</label><input name="nombre" value="<?= old('nombre', $producto['nombre'] ?? '') ?>" required><label>Descripción</label><textarea name="descripcion"><?= old('descripcion', $producto['descripcion'] ?? '') ?></textarea><label>Precio</label><input type="number" step="0.01" min="0" name="precio" value="<?= old('precio', $producto['precio'] ?? '') ?>" required><label>Imagen</label><input name="imagen" value="<?= old('imagen', $producto['imagen'] ?? '') ?>" placeholder="gelatina.jpeg"><input type="hidden" name="estado" value="<?= $producto['estado'] ?? 1 ?>"><button class="button" type="submit">Guardar</button></form></div><?= $this->endSection() ?>
